PYTHONDONTWRITEBYTECODE=1 python -B - <<'PY'
import hashlib, re
from pathlib import Path
for name in ['README.md','docs/public-api.md','AGENTS.md','docs/dev/reports/phases/2/2.1.md']:
    path=Path(name); text=path.read_text(); lines=text.splitlines()
    for i,line in enumerate(lines):
        if line.startswith('#') and i+1<len(lines): assert not lines[i+1].strip(), (name,i+1,'heading spacing')
    for target in re.findall(r'\]\(([^)]+)\)',text):
        if '://' not in target and not target.startswith('#'):
            assert (path.parent/target.split('#')[0]).exists(), (name,target)
    print(name,hashlib.sha256(path.read_bytes()).hexdigest(),'headings/local links verified')
PY

